scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;
	If ($Event == 370) @Event370;
	
	Return;
	
@Event280:
	Say("张琳心：西岳华山以险著称，果然名不虚传！", 21);
	Return;	
	
@Event290:
	If ($Talk048290 == 0) @Talk0;
	If ($Talk048290 == 1) @Talk1;
@Talk0:
	Say("张琳心：想不到华山派的弟子竟这样蛮横无礼！", 21);
	Say("独孤剑：现在上不了山，可如何是好？", 1);
	Say("张琳心：哼！我就不信这华山是什么龙潭虎穴，不如我们闯上去好了！那几个华山弟子根本就不是我们的对手。", 21);
	Say("独孤剑：不妥，我们此次前来原是一番好意，如果意气用事得罪了顾枫顾大侠的弟子，岂不是有背初衷？", 1);
	Say("张琳心：可是“自古华山一条路”，不从正门上，又能从哪里上山呢？", 21);
	Say("独孤剑：我们还是回石塘镇打听打听，看看有什么别的办法。", 1);
	Assign($Talk048290, 1);
	Return;	
@Talk1:	
	Say("独孤剑：我们还是回石塘镇打听打听，看看有什么别的办法。", 1);
	Return;	
	
@Event320:
	Say("张琳心：上山的时候得小心别让华山弟子发现了。", 21);
	Return;	
	
@Event360:
	Say("张琳心：我们这就去长安找那个华山弟子吧。", 21);
	Return;	
	
@Event370:
	Say("张琳心：独孤哥哥，华山的事已经办完了，我们去少林寺吧。", 21);
	Say("独孤剑：好。", 1);
	Return;

scripts.华山派弟子对话.txt:
// 与守在山门口的华山派弟子的对话

	If ($Event << 350) @EventLess350;
		
	Return;
	
@EventLess350:
	If ($Talkhuashan == 0) @Talkhuashan0;
	If ($Talkhuashan == 1) @Talkhuashan1;
	
@Talkhuashan0:	
	Say("华山弟子：喂喂喂！看什么看！有请柬没有？", 0);
	Say("独孤剑：两位兄台，在下衡山掌门独孤剑，有要事要上华山面陈顾大侠，请两位行个方便。", 1);
	Say("华山弟子：什么？掌门？有没有搞错，看你嘴上无毛，办事不牢，衡山什么时候来了个乳臭未干的掌门了！", 0);
	Say("华山弟子：我看八成是刘轻舟练了返老还童功了！哈哈哈哈……", 0);
	Say("独孤剑：你们敢侮辱先师……", 9);
	Say("张琳心：独孤哥哥！", 21);
	Say("华山弟子：你既然说自己是什么掌门，那你有华山的请柬吗？", 0);
	Say("独孤剑：什么请柬？", 8);
	Say("华山弟子：华山正在比武选举掌门，已发下武林帖，广邀天下英雄前来见证。", 0);
	Say("独孤剑：在下下山已久，故并未接到武林帖。", 1);
	Say("华山弟子：哼！又是一个混水摸鱼想蹭饭吃的，一天总会碰上几个这样的人，你当我们华山是什么地方！走开！", 0);
	Say("华山弟子：走开！想吃白食到别处去打主意！", 0);
	Assign($Talkhuashan, 1);
	Assign($Event, 290);
	Memo("独孤剑和张琳心来到华山脚下，得知华山正在举行争夺掌门之位的比武，二人因无请帖而无法上山。");
	Return;

@Talkhuashan1:
	Say("华山弟子：今日华山派选举掌门之日，闲杂人等一律走开。", 0);
	Return;

