traps.trap02.txt:
// 切换到map061华山栈道2

	If ($Event << 320) @EventLess320;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;
	If ($Event == 370) @Event370;
	
	FadeOut();
	SaveNpc();
	SaveObj();	
	LoadMap("map061_华山栈道2.map");
	LoadNpc("map061.npc");
	SaveNpc("temp_map061.npc");  //有反复战斗
	LoadObj("map061.obj");
	SetPlayerPos(4, 141);
	SetPlayerDir(5);
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	FadeIn();
	Return;
	
@EventLess320:
	Return;
	
@Event320:
	Say("李三：就是这了，这是俺几年前上山采药时发现的。", 70);
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("凝弦.mp3");
	LoadMap("map061_华山栈道2.map");
	LoadMap("map061_华山栈道2.map");
	LoadNpc("map061.npc");
	SaveNpc("temp_map061.npc");  //有反复战斗
	LoadObj("map061.obj");
	SetPlayerPos(4, 141);
	SetPlayerDir(5);
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	FadeIn();
	Say("李三：这座山名唤“一秤峰”。两位可能不知，这里原有个典故：这半山腰有铁瓦亭一座，铁棋一枰，据说当年太祖皇帝曾在这里和陈抟老祖下棋，下到一半就输了，结果把华山输给了老祖。这亭于是便叫“赌棋亭”，这峰就被称作“一秤峰”。", 70);
	Say("张琳心：想不到华山还有这许多故事。", 21);
	SetNpcScript("张琳心", "");
	SetNpcScript("李三", "");
	Return;
	
@Event360:
	Say("张琳心：现在又上华山作什么？", 21);	
	Return;
	
@Event370:
	Say("张琳心：独孤哥哥，我们不要乱逛了，快去少林寺吧。", 21);
	Return;

