traps.trap04.txt:
// 地图左上方，非剧情的 Trap，烘托氛围

	If ($gantan == 0) @Talk0;
	If ($gantan == 1) @Talk1;
	
@Talk0:	
	SetNpcKind("张琳心", 1);
	PlayerGoto(1, 15);
	SetPlayerDir(3);
	NpcGoto("张琳心"2, 14);
	SetNpcDir("张琳心", 3);
	Say("独孤剑：从此地远远望去，华山四面如削，五峰对峙，险峻非常，真不愧“奇险天下第一山”之称！", 2);
	Say("张琳心：华山以奇险峻秀冠天下，古人有“东岳独尊，中岳独雄，北岳独高，南岳独秀，西岳独险”之说，巍巍五岳，各具特色。", 21);
	Say("独孤剑：可惜我大好河山，如今却惨遭金人铁蹄践踏，此仇此恨，真让人睡不安寝，食不知味！", 1);
	Say("张琳心：最可恨的是昏君佞臣只知道偏安享乐，置老百姓于水深火热于不顾！", 27);
	Say("独孤剑：他日有机会，我一定要上战场杀敌，方不负我这一身武功！", 1);
	SetNpcDir("张琳心", 1);
	Say("张琳心：我也要去！", 21);
	SetPlayerDir(5);
	Say("独孤剑：你是一个女孩子，如何能上战场？", 2);
	Say("张琳心：女孩子怎么啦，谁说女孩子不能上阵杀敌？当年杨门女将巾帼不让须眉，不一样将入侵的辽人杀得铩羽而归？", 23);
	Say("独孤剑：哈哈哈！好好好，到时我们一起上阵杀敌，让那些金人知道，如今的大宋同样也有巾帼英豪、女中丈夫！", 2);
	Say("张琳心：好，咱们一言为定！", 95);
	Say("独孤剑：一言为定！", 2);
	SetNpcKind("张琳心", 3);
	Assign($gantan, 1);
	Return;

@Talk1:
	Return;

